CREATE OR REPLACE FUNCTION public.reconcile_cf_image_status(p_cf_id text, p_exists boolean) RETURNS TABLE(action text, rows_affected int) LANGUAGE plpgsql SECURITY DEFINER AS $$ DECLARE v_now timestamptz := now(); v_rows int := 0; BEGIN IF p_exists THEN UPDATE public.product_images SET cf_sync_status = 'verified', cf_verified_at = COALESCE(cf_verified_at, v_now), cf_last_checked_at = v_now, cf_last_error = NULL, last_modified_source = 'edge_function', updated_at = v_now WHERE cloudflare_image_id = p_cf_id AND deleted_at IS NULL AND cf_sync_status <> 'verified'; GET DIAGNOSTICS v_rows = ROW_COUNT; RETURN QUERY SELECT 'mark_verified'::text, v_rows; ELSE UPDATE public.product_images SET cf_sync_status = 'missing', cf_check_attempts = cf_check_attempts + 1, cf_last_checked_at = v_now, cf_last_error = COALESCE(cf_last_error, '') || ' | ' || v_now::text || ' recon: not_found_in_cloudflare', last_modified_source = 'edge_function', updated_at = v_now WHERE cloudflare_image_id = p_cf_id AND deleted_at IS NULL AND cf_sync_status = 'verified'; GET DIAGNOSTICS v_rows = ROW_COUNT; RETURN QUERY SELECT 'mark_missing'::text, v_rows; END IF; END; $$;;
